"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["normalizeActivity"]);
const { normalizeActivity } = api;

const shared = {
  author: { name: "Bea", avatar: "bea.png" },
  ageMinutes: 0,
  text: "",
  media: [],
  link: null,
  counts: { likes: 0, replies: 1, shares: 2 },
  shared: null
};
const input = {
  author: { name: "Ari", avatar: "ari.png" },
  ageMinutes: 42,
  text: "Update",
  media: [
    { type: "image", source: "one.jpg" },
    { type: "clip", source: "two.mp4" }
  ],
  link: { title: "Details", thumbnail: "thumb.jpg", address: "https://example.test" },
  counts: { likes: 3, replies: 4, shares: 5 },
  shared
};
const normalized = normalizeActivity(input);
assert.deepStrictEqual(normalized, input);
assert.notStrictEqual(normalized, input);
assert.notStrictEqual(normalized.author, input.author);
assert.notStrictEqual(normalized.media, input.media);
assert.notStrictEqual(normalized.media[0], input.media[0]);
assert.notStrictEqual(normalized.link, input.link);
assert.notStrictEqual(normalized.counts, input.counts);
assert.notStrictEqual(normalized.shared, input.shared);
assert.notStrictEqual(normalized.shared.author, input.shared.author);

input.author.name = "Changed";
input.media[0].source = "changed.jpg";
input.media.push({ type: "image", source: "three.jpg" });
input.link.title = "Changed";
input.counts.likes = 99;
shared.author.name = "Changed shared";
assert.strictEqual(normalized.author.name, "Ari");
assert.strictEqual(normalized.media.length, 2);
assert.strictEqual(normalized.media[0].source, "one.jpg");
assert.strictEqual(normalized.link.title, "Details");
assert.strictEqual(normalized.counts.likes, 3);
assert.strictEqual(normalized.shared.author.name, "Bea");

const minimal = {
  author: { name: "N", avatar: "a" },
  ageMinutes: 0,
  media: [],
  counts: { likes: 0, replies: 0, shares: 0 }
};
assert.deepStrictEqual(normalizeActivity(minimal), {
  author: { name: "N", avatar: "a" },
  ageMinutes: 0,
  text: null,
  media: [],
  link: null,
  counts: { likes: 0, replies: 0, shares: 0 },
  shared: null
});

function valid(overrides = {}) {
  return {
    author: { name: "Name", avatar: "avatar" },
    ageMinutes: 1,
    media: [],
    counts: { likes: 0, replies: 0, shares: 0 },
    ...overrides
  };
}

const malformed = [
  null,
  [],
  valid({ author: null }),
  valid({ author: { name: "", avatar: "a" } }),
  valid({ author: { name: "n", avatar: "" } }),
  valid({ ageMinutes: -1 }),
  valid({ ageMinutes: 1.5 }),
  valid({ text: null }),
  valid({ media: null }),
  valid({ media: [{ type: "video", source: "x" }] }),
  valid({ media: [{ type: "image", source: "" }] }),
  valid({ media: [null] }),
  valid({ link: {} }),
  valid({ link: { title: "", thumbnail: "t", address: "a" } }),
  valid({ link: { title: "t", thumbnail: "", address: "a" } }),
  valid({ counts: null }),
  valid({ counts: { likes: -1, replies: 0, shares: 0 } }),
  valid({ counts: { likes: 0, replies: 0.5, shares: 0 } }),
  valid({ counts: { likes: 0, replies: 0, shares: "0" } }),
  valid({ shared: 1 })
];
for (const value of malformed) {
  assert.throws(() => normalizeActivity(value), TypeError);
}

const selfCycle = valid();
selfCycle.shared = selfCycle;
assert.throws(() => normalizeActivity(selfCycle), TypeError);
const first = valid();
const second = valid();
first.shared = second;
second.shared = first;
assert.throws(() => normalizeActivity(first), TypeError);

